import { NextResponse } from "next/server";
import { requireAdminApi as requireAdmin } from "@/lib/store/permissions";
import { connectDatabase } from "@/lib/database";
import { Campaign, Order } from "@/models";
import { csvCell } from "@/lib/store/admin";
export async function GET(): Promise<NextResponse> { try { await requireAdmin(); await connectDatabase(); const orders = await Order.find({ status: { $in: ["confirmed", "ready_for_pickup", "collected"] } }).lean(); const campaignIds = [...new Set(orders.flatMap((order) => order.items.map((item) => item.campaignId.toString())))]; const campaigns = await Campaign.find({ _id: { $in: campaignIds } }).lean(); const groups = new Map<string, { design: string; garment: string; size: string; quantity: number; sku: string; campaign: string; notes: string }>(); for (const order of orders) for (const item of order.items) { const campaign = campaigns.find((value) => value._id.toString() === item.campaignId.toString()); const key = `${item.productTitle}|${item.garmentType}|${item.size}|${item.sku}`; const current = groups.get(key); if (current) current.quantity += item.quantity; else groups.set(key, { design: item.productTitle, garment: item.garmentType, size: item.size, quantity: item.quantity, sku: item.sku, campaign: campaign?.name ?? item.campaignId.toString(), notes: campaign?.vendorNotes ?? "" }); } const rows = [["Design", "Garment Type", "Size", "Quantity", "SKU", "Campaign", "Vendor Notes"], ...[...groups.values()].map((item) => [item.design, item.garment, item.size, item.quantity, item.sku, item.campaign, item.notes])]; const csv = rows.map((row) => row.map(csvCell).join(",")).join("\r\n"); return new NextResponse(csv, { headers: { "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": "attachment; filename=mask-vendor-orders.csv", "Cache-Control": "private, no-store" } }); } catch { return NextResponse.json({ error: "Forbidden" }, { status: 403 }); } }
